draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // Draw book
  ctx.fillStyle = '#663300';
  ctx.fillRect(W/2-50, H/2-50, 100, 100);
  ctx.lineWidth = 3;
  ctx.strokeStyle = 'black';
  ctx.strokeRect(W/2-50, H/2-50, 100, 100);

  // Draw stick figure
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2, H/2+70, 20, 0, 2*Math.PI);
  ctx.fill();
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.moveTo(W/2, H/2+50);
  ctx.lineTo(W/2, H/2+90);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2+70);
  ctx.lineTo(W/2-30, H/2+100);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2+70);
  ctx.lineTo(W/2+30, H/2+100);
  ctx.stroke();

  // Draw wisdom lines
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.moveTo(W/2-40, H/2-30);
  ctx.lineTo(W/2-40+50*Math.sin(t), H/2-30);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2+40, H/2-30);
  ctx.lineTo(W/2+40+50*Math.sin(t+Math.PI), H/2-30);
  ctx.stroke();

  ctx.restore();
}
